  public static AgentTaskState TaskState(LegacySnapshot data,int index){var state=data==null||data.Activity==null?new AgentTaskState():index==0?data.Activity.Codex:data.Activity.Claude;return index==1&&state.Source=="claude-code-hooks"?new AgentTaskState():state;}
  public static Color AgentColor(AgentTaskState task,DateTimeOffset now){switch(task.Effective(now)){case "working":return Good;case "idle":return Color.FromArgb(164,211,230);case "waiting":return Warm;case "error":return Bad;default:return Color.FromArgb(213,223,233);}}
  public static Color DesktopAgentColor(LegacySnapshot data,int index,DateTimeOffset now){bool known=data!=null&&data.IsFresh(now)&&(index==0?data.CodexKnown:data.ClaudeKnown),up=data!=null&&(index==0?data.CodexRun:data.ClaudeUp);return known&&up?AgentColor(TaskState(data,index),now):Color.FromArgb(213,223,233);}
  public static string DesktopAgentLabel(LegacySnapshot data,int index,DateTimeOffset now,bool compact){bool known=data!=null&&data.IsFresh(now)&&(index==0?data.CodexKnown:data.ClaudeKnown),up=data!=null&&(index==0?data.CodexRun:data.ClaudeUp);if(!known)return compact?"未知":"应用状态未知";if(!up)return "未运行";var task=TaskState(data,index);return task.Fresh(now)&&task.Effective(now)!="offline"?task.Label(now):(index==0?"状态不可用":"在线");}
  public static bool DesktopAgentWorking(LegacySnapshot data,int index,DateTimeOffset now){return data!=null&&data.IsFresh(now)&&(index==0?data.CodexKnown&&data.CodexRun:data.ClaudeKnown&&data.ClaudeUp)&&TaskState(data,index).Effective(now)=="working";}
  public static string DesktopAgentHint(LegacySnapshot data,int index,DateTimeOffset now){var task=TaskState(data,index);string title=index==0?"Codex 桌面":"Claude 桌面",label=DesktopAgentLabel(data,index,now,false);if(task.Source=="codex-file-activity-estimate"&&task.Fresh(now))return title+"："+label+"（根据近期文件活动估计）";if(label=="在线"||label=="状态不可用")return title+"：在线。暂时无法获取任务状态。";if(label=="未运行")return title+"：未检测到桌面应用。";if(label=="应用状态未知")return title+"：暂时无法确认应用状态。";return title+"："+label+" · 已验证的任务事件";}
  public static Bitmap RenderLive(int width,int height,int margin,LegacySnapshot snapshot,int page,double phase){var frame=new StatusFrameData(snapshot,page,phase);return Render(width,height,margin,frame.Snapshot,frame.Current,frame.Next,frame.Phase);}
  public static Bitmap RenderLiveWithBattery(int width,int height,int margin,LegacySnapshot snapshot,int page,double phase,DeviceBatterySnapshot batteries){var frame=new StatusFrameData(snapshot,page,phase);return RenderWithBattery(width,height,margin,frame.Snapshot,frame.Current,frame.Next,frame.Phase,batteries);}
  static Color MetricColor(double? n,bool fresh){return !fresh||!n.HasValue||n<0||n>100||Double.IsNaN(n.Value)||Double.IsInfinity(n.Value)?Palette.Secondary:n>=90?Bad:n>=75?Warm:Palette.Accent;}
  static string Number(double? n,bool fresh){return !fresh||!n.HasValue||Double.IsNaN(n.Value)||Double.IsInfinity(n.Value)||n<0||n>100?"\u2014":Math.Max(0,Math.Min(100,n.Value)).ToString("0.0")+"%";}
  static void Dot(Graphics g,float x,float y,Color color){Dot(g,x,y,color,5,1);}
  static void Dot(Graphics g,float x,float y,Color color,float size,double opacity){int alpha=(int)Math.Round(Math.Max(0,Math.Min(1,opacity))*color.A);using(var b=new SolidBrush(Color.FromArgb(alpha,color.R,color.G,color.B)))g.FillEllipse(b,x,y,size,size);}
  public static Bitmap Render(int width,int height,int margin,LegacySnapshot data,string ticker){return Render(width,height,margin,data,ticker,null,0);}
  public static Bitmap Render(int width,int height,int margin,LegacySnapshot data,string ticker,string next,double phase){return RenderWithBattery(width,height,margin,data,ticker,next,phase,null);}
