   StatusSignal.From(data).Paint(g,width,height);if(height<232){StatusPerformance.PaintTicker(g,new RectangleF(27,7,width-110,23),body,text,ticker,next,phase);for(int i=0;i<2;i++){var icon=StatusUiLayout.ServiceIcon(i,width,height);bool known=data!=null&&(i==0?data.CodexKnown:data.ClaudeKnown),up=data!=null&&(i==0?data.CodexRun:data.ClaudeUp);int slot=Math.Max(1,(width-54)/2);var task=TaskState(data,i);Text(g,(i==0?"Codex":"Claude")+" · "+DesktopAgentLabel(data,i,DateTimeOffset.UtcNow,height<232),small,text,new RectangleF(icon.Right+6,36,slot-39,22),StringAlignment.Near);Dot(g,icon.Left+slot-14,45,DesktopAgentColor(data,i,DateTimeOffset.UtcNow));}}
   else{Text(g,"\u72b6\u6001\u53f0",title,text,StatusUiLayout.HeaderTitle(width),StringAlignment.Near);StatusPerformance.PaintTicker(g,StatusUiLayout.HeaderTicker(width),small,muted,ticker,next,phase);using(var p=new Pen(Color.FromArgb(24,255,255,255)))g.DrawLine(p,StatusUiLayout.ContentInset,61,width-StatusUiLayout.ContentInset,61);
    var numbers=data==null?new double?[]{null,null,null,null}:new[]{data.Cpu,data.Memory,data.DiskD,data.Gpu};string[] labels={"CPU Utility","\u5185\u5b58","\u786c\u76d8 D","GPU · NVIDIA"};for(int i=0;i<4;i++){var r=StatusUiLayout.Metric(i,width);var label=StatusUiLayout.MetricLabel(i,width);var valueRect=StatusUiLayout.MetricValue(i,width);Text(g,labels[i],body,muted,label,StringAlignment.Near);string metric=Number(numbers[i],fresh);if(i==3&&fresh&&data.GpuUsedMb.HasValue&&data.GpuTotalMb.HasValue)metric+="  "+(data.GpuUsedMb.Value/1024).ToString("0.0")+"/"+(data.GpuTotalMb.Value/1024).ToString("0.#")+" GiB";Text(g,metric,value,text,valueRect,StringAlignment.Far);var track=StatusUiLayout.MetricTrack(i,width);using(var p=GlassSurface.Path(track,1.5f))using(var b=new SolidBrush(Color.FromArgb(24,255,255,255)))g.FillPath(b,p);if(fresh&&numbers[i].HasValue&&numbers[i]>=0&&numbers[i]<=100&&!Double.IsNaN(numbers[i].Value)){float fill=(float)(track.Width*Math.Max(0,Math.Min(100,numbers[i].Value))/100);if(fill>1)using(var p=GlassSurface.Path(new RectangleF(track.X,track.Y,fill,track.Height),1.5f))using(var b=new SolidBrush(MetricColor(numbers[i],fresh)))g.FillPath(b,p);}}
    for(int i=0;i<2;i++){var r=StatusUiLayout.Service(i,width);bool known=data!=null&&(i==0?data.CodexKnown:data.ClaudeKnown),up=data!=null&&(i==0?data.CodexRun:data.ClaudeUp);using(var p=GlassSurface.Path(r,StatusUiLayout.ServiceRadius))using(var b=new LinearGradientBrush(r,Color.FromArgb(110,9,20,31),Color.FromArgb(72,9,20,31),LinearGradientMode.Vertical))g.FillPath(b,p);Text(g,i==0?"Codex":"Claude",name,known&&up?text:muted,new RectangleF(r.Left+51,r.Top+18,r.Width-59,25),StringAlignment.Near);var task=TaskState(data,i);Dot(g,r.Right-17,r.Top+12,DesktopAgentColor(data,i,DateTimeOffset.UtcNow));Text(g,DesktopAgentLabel(data,i,DateTimeOffset.UtcNow,height<232),small,muted,new RectangleF(r.Left+10,r.Top+46,r.Width-20,18),StringAlignment.Center);}
    var net=data==null?new NetworkReadonlySnapshot():data.Network;var route=StatusUiLayout.Connection(0,width);var routeLabel=StatusUiLayout.RouteLabel(width);Text(g,"网站耗时",small,muted,routeLabel,StringAlignment.Near);string current=WebsiteLatency.Label(DateTimeOffset.UtcNow);Text(g,current,small,text,StatusUiLayout.RouteValue(width),StringAlignment.Far);var testButton=StatusUiLayout.WebsiteTestHit(width);using(var buttonPath=GlassSurface.Path(testButton,StatusUiLayout.ButtonRadius))using(var buttonFill=new SolidBrush(Color.FromArgb(18,255,255,255)))using(var buttonEdge=new Pen(Color.FromArgb(55,255,255,255),1)){g.FillPath(buttonFill,buttonPath);g.DrawPath(buttonEdge,buttonPath);}Text(g,"测速",small,text,testButton,StringAlignment.Center);
    var balance=StatusUiLayout.Connection(1,width);Text(g,"DeepSeek",small,muted,StatusUiLayout.BalanceLabel(width),StringAlignment.Near);var account=data==null?new BalanceReadonlySnapshot():data.Balance;Text(g,account.Label(DateTimeOffset.UtcNow),small,account.Fresh(DateTimeOffset.UtcNow)?account.Available?Good:Warm:muted,StatusUiLayout.BalanceValue(width),StringAlignment.Far);
    for(int i=0;i<2;i++){var r=StatusUiLayout.Voice(i,width);using(var p=GlassSurface.Path(r,StatusUiLayout.VoiceRadius))using(var b=new SolidBrush(Color.FromArgb(15,255,255,255)))g.FillPath(b,p);string pack=data==null?"":i==0?data.CodexVoice:data.ClaudeVoice;Text(g,VoicePackStore.Label(pack),small,data!=null&&data.VoiceAvailable?text:muted,new RectangleF(r.X+7,r.Y,r.Width-14,r.Height),StringAlignment.Center);}
   }DrawBatteryRow(g,width,height<232,batteries);g.ResetTransform();
   var cc=StatusUiLayout.CcSwitchButton(width,height<232);cc.Offset(margin,margin);using(var pen=new Pen(Color.FromArgb(CcSwitchAvailable?205:75,Palette.Text),1.4f)){g.DrawArc(pen,cc.Left+4,cc.Top+5,12,12,40,280);g.DrawArc(pen,cc.Left+8,cc.Top+8,12,12,220,280);}
