  public static void DrawBatteryRow(Graphics g,int width,bool compact,DeviceBatterySnapshot batteries){
   if(g==null)return;var now=DateTimeOffset.UtcNow;var muted=SystemInformation.HighContrast?SystemColors.WindowText:Color.FromArgb(196,208,220);var text=Palette.Text;
   for(int i=0;i<3;i++){var slot=StatusUiLayout.BatterySlot(i,width,compact);if(slot.IsEmpty||slot.Width<48)continue;var device=batteries==null?null:batteries.Slot(i);bool available=device!=null&&device.Available(now);Color color=available?text:muted;DrawBatteryIcon(g,StatusUiLayout.BatteryIcon(i,width,compact),device,now,color);Text(g,i==0?"Mac":i==1?"iPad":"手机",batteryLabel,muted,StatusUiLayout.BatteryLabel(i,width,compact),StringAlignment.Near);string valueText=available?device.Value(now):"不可用";Text(g,valueText,batteryValue,color,StatusUiLayout.BatteryValue(i,width,compact),StringAlignment.Far);}
  }
  static void DrawBatteryIcon(Graphics g,Rectangle rect,DeviceBatterySlot slot,DateTimeOffset now,Color color){
   if(rect.IsEmpty)return;float x=rect.X,y=rect.Y;using(var pen=new Pen(Color.FromArgb(220,color),1.1f))using(var fillTrack=new SolidBrush(Color.FromArgb(26,color))){g.DrawRectangle(pen,x,y+1,11,8);g.FillRectangle(fillTrack,x+12,y+3,2,4);if(slot!=null&&slot.Available(now)){float level=(float)Math.Max(0,Math.Min(100,slot.Sample.Level.Value));if(level>0){using(var fill=new SolidBrush(color))g.FillRectangle(fill,x+2,y+3,Math.Max(1,7*level/100f),4);}}if(slot!=null&&slot.Available(now)&&slot.Sample.Charging==true){using(var bolt=new Pen(Color.FromArgb(245,color),1.1f)){g.DrawLine(bolt,x+7,y+1,x+5,y+5);g.DrawLine(bolt,x+5,y+5,x+8,y+5);g.DrawLine(bolt,x+8,y+5,x+6,y+9);}}}
  }
